// Host build: resetting an overlay's variables when it is loaded (overlay.c; the table, modern/gen/overlay_table.c,
// and the units' variable lists are generated by tools/host_overlay_vars.py). See docs/host.md.
#ifndef HOST_OVERLAY_H
#define HOST_OVERLAY_H

#include "host_overlay_vars.h"

// one overlay unit (src/ovNNN/<unit>.cpp): its variables and its explicit static initialiser
typedef struct {
    unsigned id;                   // the overlay
    const HostOverlayVar *vars;    // HOST_OVERLAY_VARS_END-terminated, or NULL
    void (*staticInit)(void);      // StaticInit_<unit>, or NULL
} HostOverlayUnit;

extern const HostOverlayUnit gHostOverlayUnits[];
extern const unsigned gHostOverlayUnitCount;

// main(), before the game starts: take the copy of the overlays' variables that loads restore
void HostOverlay_Init(void);

// FS_StartOverlay: overlay id was loaded
void HostOverlay_Load(unsigned id);

#endif
